from __future__ import annotations

from pathlib import Path

DASHBOARD = Path("docs/index.html")
STYLE_ID = "v4-player-props-ux-style"
SCRIPT_ID = "v4-player-props-ux-script"

STYLE = r'''<style id="v4-player-props-ux-style">
.propsUxSummary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}.propsUxMetric{border:1px solid var(--line);background:#091321;border-radius:14px;padding:12px}.propsUxMetric strong{display:block;color:var(--green);font-size:22px;margin-top:4px}.propsUxTop{border:1px solid rgba(0,227,155,.45);background:linear-gradient(180deg,rgba(0,227,155,.08),#08101c);border-radius:16px;padding:14px;margin-bottom:14px}.propsUxTopPick{font-size:22px;font-weight:900;color:var(--green);margin-top:4px}.propsUxSticky{position:sticky;top:0;z-index:12;background:rgba(5,11,20,.96);backdrop-filter:blur(12px);padding:10px 0 12px;border-bottom:1px solid #18253a}.propsUxTools{display:grid;grid-template-columns:1.2fr repeat(4,minmax(120px,.7fr)) auto;gap:10px}.propsUxTools input,.propsUxTools select,.propsUxClear{width:100%;height:44px;background:#07101d;border:1px solid var(--line);color:#fff;border-radius:12px;padding:10px}.propsUxClear{cursor:pointer;font-weight:900;color:#9fb0cb}.propsUxChips{display:flex;gap:8px;overflow:auto;padding:9px 0 2px}.propsUxChip{white-space:nowrap;border:1px solid #2a3d5d;background:#0a1423;color:#b9c8df;border-radius:999px;padding:7px 11px;font-size:11px;font-weight:900}.propsUxChip.active{border-color:var(--green);color:var(--green);background:rgba(0,227,155,.1)}.propsUxMeta{display:flex;justify-content:space-between;gap:10px;align-items:center;margin:8px 0;color:var(--muted);font-size:11px}.propsUxTable{overflow:auto;border:1px solid var(--line);border-radius:16px}.propsUxHead,.propsUxRow{display:grid;grid-template-columns:minmax(190px,1.3fr) 65px 70px 95px 95px 90px 90px 80px;gap:10px;align-items:center;min-width:930px}.propsUxHead{position:sticky;top:0;padding:12px;background:#070b13;color:#7f8da7;text-transform:uppercase;font-size:11px;letter-spacing:.08em}.propsUxHead button{border:0;background:transparent;color:inherit;font:inherit;font-weight:800;cursor:pointer;padding:0;text-align:left}.propsUxHead button.active{color:var(--green)}.propsUxRow{padding:13px 12px;border-top:1px solid #152034}.propsUxPlayer{font-weight:900}.propsUxSub{color:var(--muted);font-size:11px;margin-top:3px}.propsUxSignal{font-weight:900;color:var(--green)}.propsUxBad{color:var(--red)}.propsUxCards{display:none}.propsUxCard{border:1px solid var(--line);background:#08101c;border-radius:14px;padding:13px}.propsUxCardTop{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.propsUxCardPick{font-size:18px;font-weight:900;color:var(--green);margin-top:5px}.propsUxCardGrid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px;margin-top:9px}.propsUxCardLine{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid #152034;font-size:12px}.propsUxBadge{display:inline-flex;border:1px solid rgba(0,227,155,.45);background:rgba(0,227,155,.12);color:var(--green);border-radius:999px;padding:4px 8px;font-size:10px;font-weight:900}.propsUxDetails{display:none;margin-top:10px;padding-top:9px;border-top:1px solid #1a2940}.propsUxCard.open .propsUxDetails{display:block}.propsUxExpand{width:100%;margin-top:9px;border:1px solid #2a3d5d;background:#0b1626;color:#b9c8df;border-radius:10px;padding:8px;font-weight:900}.propsUxHistory{display:flex;gap:5px;flex-wrap:wrap;margin-top:6px}.propsUxHistory span{min-width:34px;text-align:center;border:1px solid #21466a;background:#0a2530;color:#8ff4d2;border-radius:8px;padding:5px}.propsUxEmpty{text-align:center;color:var(--muted);padding:35px}
@media(max-width:900px){.propsUxSummary{grid-template-columns:1fr 1fr}.propsUxSticky{top:0}.propsUxTools{grid-template-columns:1fr 1fr}.propsUxTools input{grid-column:1/-1}.propsUxClear{grid-column:1/-1}.propsUxTable{display:none}.propsUxCards{display:grid;gap:10px}.propsUxCardGrid{grid-template-columns:1fr}.propsUxMeta{align-items:flex-start;flex-direction:column}.propsUxTopPick{font-size:18px}}
@media(max-width:520px){.propsUxTools{grid-template-columns:1fr}.propsUxTools input,.propsUxClear{grid-column:auto}.propsUxSummary{grid-template-columns:1fr 1fr}}
</style>'''

SCRIPT = r'''<script id="v4-player-props-ux-script">
(function(){
 const arr=v=>Array.isArray(v)?v:[],esc=v=>typeof window.E==='function'?window.E(v):String(v??''),safe=(v,d='-')=>v===undefined||v===null||v===''?d:v,num=v=>{const n=Number(v);return Number.isFinite(n)?n:null};
 const state={sort:'score',dir:-1,quick:''};
 const raw=()=>typeof window.propsRaw==='function'?arr(window.propsRaw()):arr(DATA?.master?.props),side=r=>String(r.signal||r.side||'OVER').toUpperCase(),line=r=>safe(r.line??r.consensus_line),score=r=>num(r.governed_score??r.calibrated_score??r.final_score??r.confidence)??0,projection=r=>num(r.projection??r.pred??r.model_projection),book=r=>safe(r.best_book||r.book||r.best_over_book||r.best_under_book,'Book TBD'),price=r=>side(r)==='UNDER'?safe(r.best_under_price??r.under_price):safe(r.best_over_price??r.over_price),game=r=>safe(r.game,'Game TBD');
 const edge=r=>{const p=projection(r),l=num(line(r));return p===null||l===null?null:Number((side(r)==='UNDER'?l-p:p-l).toFixed(2))};
 const history=r=>arr(r.last5_values).length?arr(r.last5_values):arr(r.last5).map(x=>num(x?.value??x)).filter(v=>v!==null),hitRate=r=>{const v=history(r),l=num(line(r));if(!v.length||l===null)return null;return Math.round(v.filter(x=>side(r)==='UNDER'?x<l:x>l).length/v.length*100)};
 const unique=rows=>{const m=new Map();for(const r of rows){const k=[r.player,r.stat,line(r),side(r),game(r),book(r)].join('|').toLowerCase(),o=m.get(k);if(!o||score(r)>score(o))m.set(k,r)}return [...m.values()]};
 const value=(r,k)=>k==='player'?String(r.player||'').toLowerCase():k==='stat'?String(r.stat||'').toLowerCase():k==='line'?(num(line(r))??-999):k==='edge'?(edge(r)??-999):k==='hit'?(hitRate(r)??-1):k==='price'?(num(price(r))??-9999):score(r),sorted=rows=>[...rows].sort((a,b)=>{const x=value(a,state.sort),y=value(b,state.sort);return(typeof x==='string'?x.localeCompare(y):x-y)*state.dir});
 window.setPropsUxSort=k=>{if(state.sort===k)state.dir*=-1;else{state.sort=k;state.dir=k==='player'||k==='stat'?1:-1}window.props()};
 window.setPropsQuick=q=>{state.quick=state.quick===q?'':q;window.props()};
 window.clearPropsUx=()=>{state.quick='';['pxSearch','pxStat','pxSide','pxBook','pxGame'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});window.props()};
 window.togglePropsCard=id=>document.getElementById(id)?.classList.toggle('open');
 const filters=()=>({q:String(document.getElementById('pxSearch')?.value||'').toLowerCase(),stat:String(document.getElementById('pxStat')?.value||''),side:String(document.getElementById('pxSide')?.value||''),book:String(document.getElementById('pxBook')?.value||''),game:String(document.getElementById('pxGame')?.value||'')});
 const filtered=rows=>{const f=filters();return rows.filter(r=>(!f.q||JSON.stringify(r).toLowerCase().includes(f.q))&&(!f.stat||r.stat===f.stat)&&(!f.side||side(r)===f.side)&&(!f.book||book(r)===f.book)&&(!f.game||game(r)===f.game)&&(!state.quick||(state.quick==='best'&&score(r)>=70)||(state.quick==='edge'&&(edge(r)??-99)>=2)||(state.quick==='plus'&&(num(price(r))??-999)>0)||(state.quick==='over'&&side(r)==='OVER')||(state.quick==='under'&&side(r)==='UNDER')))};
 const opts=(rows,fn)=>[...new Set(rows.map(fn).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join(''),sortBtn=(k,l)=>`<button class="${state.sort===k?'active':''}" onclick="setPropsUxSort('${k}')">${l}${state.sort===k?(state.dir>0?' ▲':' ▼'):''}</button>`;
 const summary=rows=>`<div class="propsUxSummary"><div class="propsUxMetric"><div class="label mono">Unique props</div><strong>${rows.length}</strong></div><div class="propsUxMetric"><div class="label mono">Players</div><strong>${new Set(rows.map(r=>r.player)).size}</strong></div><div class="propsUxMetric"><div class="label mono">Score 70+</div><strong>${rows.filter(r=>score(r)>=70).length}</strong></div><div class="propsUxMetric"><div class="label mono">Books</div><strong>${new Set(rows.map(book)).size}</strong></div></div>`;
 const top=rows=>{const r=[...rows].filter(x=>edge(x)!==null).sort((a,b)=>(score(b)+Math.max(edge(b),0)*3)-(score(a)+Math.max(edge(a),0)*3))[0];return r?`<div class="propsUxTop"><div class="label mono">Top player prop</div><div class="propsUxTopPick">${esc(r.player)} ${esc(side(r))} ${esc(r.stat)} ${esc(line(r))}</div><div class="small mono">${esc(game(r))} · ${esc(book(r))} ${esc(price(r))} · Projection ${esc(safe(projection(r)))} · Edge ${esc(safe(edge(r)))}</div></div>`:''};
 const row=r=>{const h=hitRate(r),e=edge(r);return `<div class="propsUxRow"><div><div class="propsUxPlayer">${esc(r.player)}</div><div class="propsUxSub mono">${esc(game(r))}</div></div><div class="propsUxSignal mono">${esc(r.stat)}</div><div>${esc(line(r))}</div><div><b>${esc(side(r))}</b><div class="propsUxSub">${esc(book(r))}</div></div><div>${esc(price(r))}</div><div>${esc(safe(projection(r)))}</div><div class="${e!==null&&e<0?'propsUxBad':''}">${esc(safe(e))}</div><div class="${h!==null&&h<50?'propsUxBad':''}">${h===null?'-':h+'%'}</div></div>`};
 const card=(r,i)=>{const h=hitRate(r),e=edge(r),vals=history(r);return `<div class="propsUxCard" id="pxc-${i}"><div class="propsUxCardTop"><div><div class="propsUxPlayer">${esc(r.player)}</div><div class="propsUxSub mono">${esc(game(r))}</div></div><span class="propsUxBadge">${esc(score(r))}</span></div><div class="propsUxCardPick">${esc(side(r))} ${esc(r.stat)} ${esc(line(r))}</div><div class="propsUxCardGrid"><div class="propsUxCardLine"><span>Best price</span><b>${esc(book(r))} ${esc(price(r))}</b></div><div class="propsUxCardLine"><span>Projection</span><b>${esc(safe(projection(r)))}</b></div><div class="propsUxCardLine"><span>Edge</span><b>${esc(safe(e))}</b></div><div class="propsUxCardLine"><span>L5 hit</span><b>${h===null?'-':h+'%'}</b></div></div><button class="propsUxExpand" onclick="togglePropsCard('pxc-${i}')">View history & details</button><div class="propsUxDetails"><div class="small mono">Recent results</div><div class="propsUxHistory">${vals.map(v=>`<span>${esc(v)}</span>`).join('')||'<span>No data</span>'}</div><div class="propsUxCardLine"><span>Matchup</span><b>${esc(game(r))}</b></div><div class="propsUxCardLine"><span>Recommendation</span><b>${esc(side(r))}</b></div></div></div>`};
 window.props=function(){const all=unique(raw()),selected={q:document.getElementById('pxSearch')?.value||'',stat:document.getElementById('pxStat')?.value||'',side:document.getElementById('pxSide')?.value||'',book:document.getElementById('pxBook')?.value||'',game:document.getElementById('pxGame')?.value||''};const rows=sorted(filtered(all));const chips=[['best','Best Bets'],['edge','Biggest Edge'],['plus','Plus Money'],['over','Overs'],['under','Unders']].map(([k,l])=>`<button class="propsUxChip ${state.quick===k?'active':''}" onclick="setPropsQuick('${k}')">${l}</button>`).join('');const controls=`<div class="propsUxSticky"><div class="propsUxTools"><input id="pxSearch" placeholder="Search player, team or matchup" oninput="props()"><select id="pxStat" onchange="props()"><option value="">All stats</option>${opts(all,r=>r.stat)}</select><select id="pxSide" onchange="props()"><option value="">All sides</option>${opts(all,side)}</select><select id="pxBook" onchange="props()"><option value="">All books</option>${opts(all,book)}</select><select id="pxGame" onchange="props()"><option value="">All games</option>${opts(all,game)}</select><button class="propsUxClear" onclick="clearPropsUx()">Clear filters</button></div><div class="propsUxChips">${chips}</div></div>`;const head=`<div class="propsUxHead"><div>${sortBtn('player','Player')}</div><div>${sortBtn('stat','Stat')}</div><div>${sortBtn('line','Line')}</div><div>Pick</div><div>${sortBtn('price','Price')}</div><div>Projection</div><div>${sortBtn('edge','Edge')}</div><div>${sortBtn('hit','L5 Hit')}</div></div>`;const html=`<div class="section"><h2 class="mono">Player Props</h2><div class="small mono">Tablet-first cards with full desktop table.</div>${summary(all)}${top(all)}${controls}<div class="propsUxMeta mono"><span>Showing ${rows.length} of ${all.length}</span><span>Sorted by ${esc(state.sort)}</span></div><div class="propsUxTable">${head}${rows.map(row).join('')||'<div class="propsUxEmpty">No props match.</div>'}</div><div class="propsUxCards">${rows.map(card).join('')||'<div class="propsUxEmpty">No props match.</div>'}</div></div>`;setTimeout(()=>Object.entries({pxSearch:selected.q,pxStat:selected.stat,pxSide:selected.side,pxBook:selected.book,pxGame:selected.game}).forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.value=v}),0);return html};
 window.PLAYER_PROPS_UX={version:'2.0',raw,unique};
})();
</script>'''

def replace_block(html: str, tag: str, marker: str, replacement: str) -> str:
    start = html.find(f'<{tag} id="{marker}">')
    if start < 0:
        return html
    end_tag = f'</{tag}>'
    end = html.find(end_tag, start)
    return html if end < 0 else html[:start] + replacement + html[end + len(end_tag):]

def main() -> None:
    if not DASHBOARD.exists():
        raise FileNotFoundError(DASHBOARD)
    html = DASHBOARD.read_text(encoding="utf-8")
    html = replace_block(html, "style", STYLE_ID, STYLE) if f'id="{STYLE_ID}"' in html else html.replace("</head>", STYLE + "\n</head>", 1)
    html = replace_block(html, "script", SCRIPT_ID, SCRIPT) if f'id="{SCRIPT_ID}"' in html else html.replace("</body>", SCRIPT + "\n</body>", 1)
    DASHBOARD.write_text(html, encoding="utf-8")
    print("Player Props UX v2 applied")

if __name__ == "__main__":
    main()
